mapper.select:
SELECT COUNT(*) FROM ( SELECT 'PROJECT' AS targetType, PROJ_NM AS title FROM TB_PROJECT WHERE DEL_YN = 'Y' UNION ALL SELECT 'CONTRACT', CONT_NM FROM TB_CONTRACT WHERE DEL_YN = 'Y' UNION ALL SELECT 'CUSTOMER', CUST_NM FROM TB_CUSTOMER WHERE DEL_YN = 'Y' UNION ALL SELECT 'ASSIGNMENT', ASSIGN_TITLE FROM TB_ASSIGNMENT WHERE DEL_YN = 'Y' UNION ALL SELECT 'BILLING', BILL_TITLE FROM TB_BILLING WHERE DEL_YN = 'Y' UNION ALL SELECT 'EMP', EMP_NM FROM TB_EMP WHERE DEL_YN = 'Y' UNION ALL SELECT 'SALES', SALES_TITLE FROM TB_SALES WHERE DEL_YN = 'Y' ) AS TOTAL WHERE 1=1
AND title LIKE CONCAT('%', #{searchKeyword}, '%')
AND targetType = #{targetType}
